import {Upload} from './vendor/supabase/upload.js';
import {cloudConfig} from './cloud-config.js';
export async function uploadOriginal(client,path,file,onProgress=()=>{},signal=null){if(signal?.aborted)throw new Error('La operación se canceló.');if(file.size<=6*1024*1024){const result=await client.storage.from('film-originals').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:true,cacheControl:'3600'});if(result.error)throw result.error;onProgress(100);return;}
 const {data,error}=await client.auth.getSession();if(error)throw error;if(!data.session)throw new Error('La sesión expiró. Ingresá nuevamente.');const base=new URL(cloudConfig.url);base.hostname=base.hostname.replace(/\.supabase\.co$/,'.storage.supabase.co');return new Promise((resolve,reject)=>{let done=false;const complete=error=>{if(done)return;done=true;signal?.removeEventListener('abort',cancel);error?reject(error):resolve();};const upload=new Upload(file,{endpoint:base.origin+'/storage/v1/upload/resumable',retryDelays:[0,1000,3000,5000],chunkSize:6*1024*1024,uploadDataDuringCreation:true,storeFingerprintForResuming:false,removeFingerprintOnSuccess:true,headers:{authorization:'Bearer '+data.session.access_token,apikey:cloudConfig.key,'x-upsert':'true'},metadata:{bucketName:'film-originals',objectName:path,contentType:file.type||'application/octet-stream',cacheControl:'3600'},onProgress:(uploaded,total)=>onProgress(Math.round(uploaded/total*100)),onError:complete,onSuccess:()=>complete()});const cancel=()=>{upload.abort().catch(()=>{});complete(new Error('La operación se canceló al cambiar de cuenta.'));};signal?.addEventListener('abort',cancel,{once:true});if(signal?.aborted)cancel();else upload.start();});}
